package org.apache.commons.math.distribution;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.MathException;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.special.Gamma;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.apache.commons.math3.exception.MathIllegalArgumentException;
import org.apache.commons.math3.exception.MathMissingException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class PoissonDistributionImpl_cumulativeProbability_TriageGen0Test {

    private static final double DELTA = 1e-10;

    @Test
    public void testCumulativeProbability_NegativeX() {
        // Testing the branch: if (x < 0) return 0;
        PoissonDistributionImpl distribution = new PoissonDistributionImpl(5.0);
        double result = distribution.cumulativeProbability(-1);
        assertEquals(0.0, result, DELTA);

        result = distribution.cumulativeProbability(Integer.MIN_VALUE);
        assertEquals(0.0, result, DELTA);
    }

    @Test
    public void testCumulativeProbability_MaxIntValue() {
        // Testing the branch: if (x == Integer.MAX_VALUE) return 1;
        PoissonDistributionImpl distribution = new PoissonDistributionImpl(5.0);
        double result = distribution.cumulativeProbability(Integer.MAX_VALUE);
        assertEquals(1.0, result, DELTA);
    }

    @Test
    public void testCumulativeProbability_NormalRange() {
        // Testing the main logic: Gamma.regularizedGammaQ
        // For Poisson, P(X <= x) = Q(x + 1, mean)
        // If mean = 1.0, P(X <= 0) = Q(1, 1)
        double mean = 1.0;
        PoissonDistributionImpl distribution = new PoissonDistributionImpl(mean);

        // x = 0
        double result = distribution.cumulativeProbability(0);
        // Manual calculation: P(X=0) = e^-1 * 1^0 / 0! = e^-1 approx 0.36787944117
        assertEquals(Math.exp(-mean), result, 1e-6);

        // x = 1
        // P(X<=1) = P(X=0) + P(X=1) = e^-1 + e^-1 = 2 * e^-1 approx 0.73575888234
        result = distribution.cumulativeProbability(1);
        assertEquals(2 * Math.exp(-mean), result, 1e-6);
    }

    @Test
    public void testCumulativeProbability_WithEpsilonAndMaxIterations() {
        // Testing the constructor that uses epsilon and maxIterations to ensure coverage of all constructors
        double mean = 2.0;
        double epsilon = 1e-12;
        int maxIterations = 100;
        PoissonDistributionImpl distribution = new PoissonDistributionImpl(mean, epsilon, maxIterations);

        double result = distribution.cumulativeProbability(2);
        // Expected P(X <= 2) for mean 2: e^-2 * (2^0/0! + 2^1/1! + 2^2/2!) = e^-2 * (1 + 2 + 2) = 5 * e^-2
        double expected = 5 * Math.exp(-2.0);
        assertEquals(expected, result, 1e-6);
    }

    @Test
    public void testCumulativeProbability_WithEpsilonOnly() {
        // Testing the constructor with epsilon
        PoissonDistributionImpl distribution = new PoissonDistributionImpl(3.0, 1e-10);
        double result = distribution.cumulativeProbability(3);
        // P(X <= 3) = e^-3 * (1 + 3 + 3^2/2 + 3^3/6) = e^-3 * (1 + 3 + 4.5 + 4.5) = 13 * e^-3
        double expected = 13 * Math.exp(-3.0);
        assertEquals(expected, result, 1e-6);
    }

    @Test
    public void testCumulativeProbability_WithMaxIterationsOnly() {
        // Testing the constructor with maxIterations
        PoissonDistributionImpl distribution = new PoissonDistributionImpl(3.0, 100);
        double result = distribution.cumulativeProbability(3);
        double expected = 13 * Math.exp(-3.0);
        assertEquals(expected, result, 1e-6);
    }
}
